// Einen Auftrag aus dem Cockpit in einzelne Anschreiben zerlegen.
// Ein Item je Empfaenger - so laesst sich jede Mail einzeln nachvollziehen,
// freigeben und im Protokoll wiederfinden.
const a = $input.first().json;
const b = a.body ?? a;
const empf = Array.isArray(b.empfaenger) ? b.empfaenger.filter((e) => e && e.email) : [];
if (empf.length === 0) throw new Error('Auftrag ohne Empfaenger - es wird nichts versendet');
if (!String(b.betreff ?? '').trim()) throw new Error('Auftrag ohne Betreff');
const stempel = Date.now();
return empf.map((e, n) => ({ json: {
  entwurfId: 'cockpit-' + stempel + '-' + n,
  objekt: b.objekt ?? null,
  modus: b.modus === 'sofort' ? 'sofort' : 'freigabe',
  durch: b.durch || 'cockpit',
  firma: e.firma ?? null,
  ansprechpartner: e.ansprechpartner ?? null,
  email: e.email,
  betreff: String(b.betreff).trim(),
  text: String(b.text ?? '').trim(),
  demoEmpfaenger: a.demoEmpfaenger ?? '',
  signaturHtml: a.signaturHtml ?? '',
  rechtshinweisHtml: a.rechtshinweisHtml ?? '',
  supabaseBasis: a.supabaseBasis,
  tabelle: a.tabelle,
} }));

// Dieselbe Sicherung wie im Follow-up: ist demoEmpfaenger gesetzt, geht jede
// Mail dorthin statt an den Investor. Der echte Empfaenger bleibt im Text
// sichtbar, damit eine Vorfuehrung zeigt, wer angeschrieben worden waere.
return $input.all().map((i) => {
  const j = { ...i.json };
  const demo = String(j.demoEmpfaenger ?? '').trim();
  if (demo === '') return { json: j };
  j.empfaengerEcht = j.email ?? '(unbekannt)';
  j.email = demo;
  j.betreff = '[VORFUEHRUNG] ' + (j.betreff ?? '');
  j.text = 'Diese Nachricht wurde umgeleitet. Echter Empfaenger waere: ' + j.empfaengerEcht +
           '\n\n--- urspruenglicher Text ---\n' + (j.text ?? '');
  return { json: j };
});

