={{ (() => {
const j = $json;
const e = (s) => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const absatz = (t) => e(t).split('\n').map((z) => z.trim() === '' ? '<div style="height:10px"></div>' : '<div style="font-size:14px;line-height:1.6;color:#16181c">' + z + '</div>').join('');
const html = '<!doctype html><html><body style="margin:0;padding:0;background:#f4f5f6">'
+ '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f6;padding:24px 12px"><tr><td align="center">'
+ '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:640px;background:#ffffff;border:1px solid #d6dade;border-radius:6px;font-family:Helvetica,Arial,sans-serif">'
+ '<tr><td style="padding:26px 28px">' + absatz(j.text) + '</td></tr>'
+ (j.signaturHtml ? '<tr><td style="padding:0 28px 22px">' + j.signaturHtml + '</td></tr>' : '')
+ (j.rechtshinweisHtml ? '<tr><td style="padding:14px 28px;border-top:1px solid #e4e7ea;font-size:11px;color:#6b727b">' + j.rechtshinweisHtml + '</td></tr>' : '')
+ '</table></td></tr></table></body></html>';
return JSON.stringify({ message: { subject: j.betreff, body: { contentType: 'HTML', content: html },
  toRecipients: [{ emailAddress: { address: j.email } }] }, saveToSentItems: true });
})() }}
